function grade(score) {
  if (score >= 90) return 'A';
  else if (score >= 80) return 'B';
  else return 'C';
}

console.log(grade(95)); // 'A'
console.log(grade(85)); // 'B'
console.log(grade(70)); // 'C'

// ternary version for a single decision
const age = 20;
console.log(age >= 18 ? 'adult' : 'minor'); // 'adult'

function dayType(day) {
  switch (day) {
    case 'Sat':
    case 'Sun':
      return 'weekend'; // both labels share this branch
    default:
      return 'weekday';
  }
}

console.log(dayType('Sun')); // 'weekend'
console.log(dayType('Mon')); // 'weekday'

